import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Tensor","description":"","frontmatter":{},"headers":[],"relativePath":"handl/reference/host-tensor/host-tensor-tensor.md","filePath":"handl/reference/host-tensor/host-tensor-tensor.md"}`),a={name:`handl/reference/host-tensor/host-tensor-tensor.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="tensor" tabindex="-1">Tensor <a class="header-anchor" href="#tensor" aria-label="Permalink to “Tensor”">​</a></h1><h2 id="tensor-tensor" tabindex="-1"><code>tensor.tensor</code> <a class="header-anchor" href="#tensor-tensor" aria-label="Permalink to “tensor.tensor”">​</a></h2><p>The <code>tensor</code> namespace record — <code>from &quot;host-tensor&quot; import tensor</code> binds</p><p>the whole surface at once (each field is the qualified-name string the <code>op</code> declarations export, so <code>tensor.matmul(a, b)</code> dispatches through <code>call_host</code> exactly like the per-name imports do).</p><h2 id="tensor-add" tabindex="-1"><code>tensor.add</code> <a class="header-anchor" href="#tensor-add" aria-label="Permalink to “tensor.add”">​</a></h2><p>elementwise <code>a + b</code> (numpy-style broadcasting).</p><p><strong>Signature:</strong> <code>tensor.add : (Tensor * Tensor) -&amp;gt; Tensor</code></p><h2 id="tensor-add-backward" tabindex="-1"><code>tensor.add_backward</code> <a class="header-anchor" href="#tensor-add-backward" aria-label="Permalink to “tensor.add_backward”">​</a></h2><p>add_backward(a, b, grad_out) -&gt; {a: da, b: db}, each unbroadcast to</p><p>the operand&#39;s shape.</p><p><strong>Signature:</strong> <code>tensor.add_backward : (Tensor * Tensor * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-batch-norm" tabindex="-1"><code>tensor.batch_norm</code> <a class="header-anchor" href="#tensor-batch-norm" aria-label="Permalink to “tensor.batch_norm”">​</a></h2><p>batch_norm(input, gamma, beta, mean, var, eps?) — variadic; <code>null</code></p><p><code>eps</code> selects the 1e-5 default.</p><p><strong>Signature:</strong> <code>tensor.batch_norm : Value... -&amp;gt; Tensor</code></p><h2 id="tensor-batch-norm-backward" tabindex="-1"><code>tensor.batch_norm_backward</code> <a class="header-anchor" href="#tensor-batch-norm-backward" aria-label="Permalink to “tensor.batch_norm_backward”">​</a></h2><p>batch_norm_backward(input, gamma, beta, mean, var, grad_out, eps?) —</p><p>primal signature + upstream grad → {input, gamma, beta} grads.</p><p><strong>Signature:</strong> <code>tensor.batch_norm_backward : Value... -&amp;gt; Value</code></p><h2 id="tensor-concat" tabindex="-1"><code>tensor.concat</code> <a class="header-anchor" href="#tensor-concat" aria-label="Permalink to “tensor.concat”">​</a></h2><p><code>xs</code> joined along <code>axis</code> (same rank, other axes equal).</p><p><strong>Signature:</strong> <code>tensor.concat : (Array * Int) -&amp;gt; Tensor</code></p><h2 id="tensor-concat-backward" tabindex="-1"><code>tensor.concat_backward</code> <a class="header-anchor" href="#tensor-concat-backward" aria-label="Permalink to “tensor.concat_backward”">​</a></h2><p>concat_backward(xs, axis, grad_out) -&gt; {xs: per-input slices}.</p><p><strong>Signature:</strong> <code>tensor.concat_backward : (Array * Int * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-conv2d" tabindex="-1"><code>tensor.conv2d</code> <a class="header-anchor" href="#tensor-conv2d" aria-label="Permalink to “tensor.conv2d”">​</a></h2><p>conv2d(input, weight, bias?, stride?, padding?, groups?) — variadic;</p><p><code>null</code> at an optional position selects the default (see the header).</p><p><strong>Signature:</strong> <code>tensor.conv2d : Value... -&amp;gt; Tensor</code></p><h2 id="tensor-conv2d-backward" tabindex="-1"><code>tensor.conv2d_backward</code> <a class="header-anchor" href="#tensor-conv2d-backward" aria-label="Permalink to “tensor.conv2d_backward”">​</a></h2><p>conv2d_backward(input, weight, grad_out, bias?, stride?, padding?,</p><p>groups?) — required primal args, then grad_out, then the primal&#39;s optionals in order; returns {input, weight, bias?}.</p><p><strong>Signature:</strong> <code>tensor.conv2d_backward : Value... -&amp;gt; Value</code></p><h2 id="tensor-derive" tabindex="-1"><code>tensor.derive</code> <a class="header-anchor" href="#tensor-derive" aria-label="Permalink to “tensor.derive”">​</a></h2><p>the adjoint op name registered for <code>name</code> (qualified or bare local), or <code>null</code>.</p><p><strong>Signature:</strong> <code>tensor.derive : String -&amp;gt; Value</code></p><h2 id="tensor-div" tabindex="-1"><code>tensor.div</code> <a class="header-anchor" href="#tensor-div" aria-label="Permalink to “tensor.div”">​</a></h2><p>elementwise <code>a / b</code> (numpy-style broadcasting).</p><p><strong>Signature:</strong> <code>tensor.div : (Tensor * Tensor) -&amp;gt; Tensor</code></p><h2 id="tensor-div-backward" tabindex="-1"><code>tensor.div_backward</code> <a class="header-anchor" href="#tensor-div-backward" aria-label="Permalink to “tensor.div_backward”">​</a></h2><p>div_backward(a, b, grad_out): da = g/b, db = −g·a/b², unbroadcast.</p><p><strong>Signature:</strong> <code>tensor.div_backward : (Tensor * Tensor * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-from-list" tabindex="-1"><code>tensor.from_list</code> <a class="header-anchor" href="#tensor-from-list" aria-label="Permalink to “tensor.from_list”">​</a></h2><p>a tensor whose flat row-major data is <code>xs</code>&#39; nested number arrays (ragged rejected).</p><p><strong>Signature:</strong> <code>tensor.from_list : Array -&amp;gt; Tensor</code></p><h2 id="tensor-matmul" tabindex="-1"><code>tensor.matmul</code> <a class="header-anchor" href="#tensor-matmul" aria-label="Permalink to “tensor.matmul”">​</a></h2><p><code>(m×k)·(k×n)</code> dense matrix product; rank-3 sides batch over <code>B</code> (batch broadcasts).</p><p><strong>Signature:</strong> <code>tensor.matmul : (Tensor * Tensor) -&amp;gt; Tensor</code></p><h2 id="tensor-matmul-backward" tabindex="-1"><code>tensor.matmul_backward</code> <a class="header-anchor" href="#tensor-matmul-backward" aria-label="Permalink to “tensor.matmul_backward”">​</a></h2><p>matmul_backward(a, b, grad_out): da = g·bᵀ, db = aᵀ·g per batch,</p><p>unbroadcast over <code>B</code> to each operand&#39;s shape.</p><p><strong>Signature:</strong> <code>tensor.matmul_backward : (Tensor * Tensor * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-max-pool" tabindex="-1"><code>tensor.max_pool</code> <a class="header-anchor" href="#tensor-max-pool" aria-label="Permalink to “tensor.max_pool”">​</a></h2><p>max_pool(input, kernel, stride?) — variadic; <code>null</code> <code>stride</code> selects</p><p>the kernel as the stride. Floor mode: trailing partial windows drop.</p><p><strong>Signature:</strong> <code>tensor.max_pool : Value... -&amp;gt; Tensor</code></p><h2 id="tensor-max-pool-backward" tabindex="-1"><code>tensor.max_pool_backward</code> <a class="header-anchor" href="#tensor-max-pool-backward" aria-label="Permalink to “tensor.max_pool_backward”">​</a></h2><p>max_pool_backward(input, grad_out, kernel, stride?, padding?):</p><p>each grad scatters to its window&#39;s argmax; returns {input}.</p><p><strong>Signature:</strong> <code>tensor.max_pool_backward : Value... -&amp;gt; Value</code></p><h2 id="tensor-mul" tabindex="-1"><code>tensor.mul</code> <a class="header-anchor" href="#tensor-mul" aria-label="Permalink to “tensor.mul”">​</a></h2><p>elementwise <code>a * b</code> (numpy-style broadcasting).</p><p><strong>Signature:</strong> <code>tensor.mul : (Tensor * Tensor) -&amp;gt; Tensor</code></p><h2 id="tensor-mul-backward" tabindex="-1"><code>tensor.mul_backward</code> <a class="header-anchor" href="#tensor-mul-backward" aria-label="Permalink to “tensor.mul_backward”">​</a></h2><p>mul_backward(a, b, grad_out): da = g·b, db = g·a, unbroadcast.</p><p><strong>Signature:</strong> <code>tensor.mul_backward : (Tensor * Tensor * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-ones" tabindex="-1"><code>tensor.ones</code> <a class="header-anchor" href="#tensor-ones" aria-label="Permalink to “tensor.ones”">​</a></h2><p>a tensor of <code>shape</code> filled with 1.0.</p><p><strong>Signature:</strong> <code>tensor.ones : (List Int) -&amp;gt; Tensor</code></p><h2 id="tensor-reshape" tabindex="-1"><code>tensor.reshape</code> <a class="header-anchor" href="#tensor-reshape" aria-label="Permalink to “tensor.reshape”">​</a></h2><p><code>t</code> re-labeled under <code>shape</code> (product must equal the element count).</p><p><strong>Signature:</strong> <code>tensor.reshape : (Tensor * (List Int)) -&amp;gt; Tensor</code></p><h2 id="tensor-reshape-backward" tabindex="-1"><code>tensor.reshape_backward</code> <a class="header-anchor" href="#tensor-reshape-backward" aria-label="Permalink to “tensor.reshape_backward”">​</a></h2><p>reshape_backward(input, shape, grad_out) -&gt; {input}.</p><p><strong>Signature:</strong> <code>tensor.reshape_backward : (Tensor * (List Int) * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-shape" tabindex="-1"><code>tensor.shape</code> <a class="header-anchor" href="#tensor-shape" aria-label="Permalink to “tensor.shape”">​</a></h2><p>the extent-per-axis list of tensor <code>t</code>.</p><p><strong>Signature:</strong> <code>tensor.shape : Tensor -&amp;gt; (List Int)</code></p><h2 id="tensor-sub" tabindex="-1"><code>tensor.sub</code> <a class="header-anchor" href="#tensor-sub" aria-label="Permalink to “tensor.sub”">​</a></h2><p>elementwise <code>a - b</code> (numpy-style broadcasting).</p><p><strong>Signature:</strong> <code>tensor.sub : (Tensor * Tensor) -&amp;gt; Tensor</code></p><h2 id="tensor-sub-backward" tabindex="-1"><code>tensor.sub_backward</code> <a class="header-anchor" href="#tensor-sub-backward" aria-label="Permalink to “tensor.sub_backward”">​</a></h2><p>sub_backward(a, b, grad_out): da = g, db = −g, unbroadcast.</p><p><strong>Signature:</strong> <code>tensor.sub_backward : (Tensor * Tensor * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-to-list" tabindex="-1"><code>tensor.to_list</code> <a class="header-anchor" href="#tensor-to-list" aria-label="Permalink to “tensor.to_list”">​</a></h2><p>the nested number arrays for tensor <code>t</code> (inverse of from_list).</p><p><strong>Signature:</strong> <code>tensor.to_list : Tensor -&amp;gt; Array</code></p><h2 id="tensor-transpose" tabindex="-1"><code>tensor.transpose</code> <a class="header-anchor" href="#tensor-transpose" aria-label="Permalink to “tensor.transpose”">​</a></h2><p><code>t</code> with axes <code>d0</code>/<code>d1</code> swapped.</p><p><strong>Signature:</strong> <code>tensor.transpose : (Tensor * Int * Int) -&amp;gt; Tensor</code></p><h2 id="tensor-transpose-backward" tabindex="-1"><code>tensor.transpose_backward</code> <a class="header-anchor" href="#tensor-transpose-backward" aria-label="Permalink to “tensor.transpose_backward”">​</a></h2><p>transpose_backward(input, d0, d1, grad_out) -&gt; {input}.</p><p><strong>Signature:</strong> <code>tensor.transpose_backward : (Tensor * Int * Int * Tensor) -&amp;gt; Value</code></p><h2 id="tensor-zeros" tabindex="-1"><code>tensor.zeros</code> <a class="header-anchor" href="#tensor-zeros" aria-label="Permalink to “tensor.zeros”">​</a></h2><p>a tensor of <code>shape</code> filled with 0.0.</p><p><strong>Signature:</strong> <code>tensor.zeros : (List Int) -&amp;gt; Tensor</code></p>`,96)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};